#include <fstream>
#include <sstream>
#include <vector>
#include <cmath>
#include <iostream>
#include <iomanip>

using namespace std;

const double EPSILON = 1e-6;

vector<double> read_numbers(const string& filename) {
    ifstream file(filename);
    string content;

    if (file) {
        content.assign((istreambuf_iterator<char>(file)), istreambuf_iterator<char>());
    } else {
        cerr << "Error opening file: " << filename << endl;
        exit(1);
    }

    istringstream iss(content);
    vector<double> numbers;
    double num;

    while (iss >> num) {
        numbers.push_back(num);
    }

    return numbers;
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        cerr << "Usage: " << argv[0] << " standard_output user_output" << endl;
        return 1;
    }

    vector<double> standard = read_numbers(argv[1]);
    vector<double> user = read_numbers(argv[2]);

    if (standard.size() != 2) {
        cerr << "Invalid standard output format." << endl;
        return 1;
    }

    if (user.size() != 2) {
        cout << "Wrong Answer" << endl;
        return 1;
    }

    double s1 = standard[0];
    double s2 = standard[1];
    double u1 = user[0];
    double u2 = user[1];

    bool correct = true;
    if (abs(u1 - s1) > EPSILON) {
        correct = false;
    }
    if (abs(u2 - s2) > EPSILON) {
        correct = false;
    }

    if (correct) {
        cout << "Accepted" << endl;
        return 0;
    } else {
        cout << "Wrong Answer" << endl;
        return 1;
    }
}

#include <iostream>
#include <fstream>
#include <string>
#include <cctype>
#include <cmath>
#include <cstdlib>
#include <algorithm>

using namespace std;

const double EPS = 1e-6;

string read_and_trim(const string &filename) {
    ifstream file(filename);
    if (!file) {
        cerr << "Error: Cannot open file '" << filename << "'" << endl;
        exit(2);
    }
    string content;
    string line;
    while (getline(file, line)) {
        content += line + '\n';
    }
    file.close();

    // Trim leading and trailing whitespace
    auto start = content.find_first_not_of(" \t\n\r");
    if (start == string::npos) {
        return "";
    }
    auto end = content.find_last_not_of(" \t\n\r");
    return content.substr(start, end - start + 1);
}

bool parse_double(const string &s, double &value) {
    char *endptr;
    const char *cstr = s.c_str();
    value = strtod(cstr, &endptr);
    if (endptr == cstr) {
        return false; // No conversion
    }
    // Check remaining characters are all whitespace
    while (*endptr != '\0') {
        if (!isspace(*endptr)) {
            return false;
        }
        endptr++;
    }
    return true;
}

bool compare_floats(double a, double b, double eps) {
    if (isnan(a) || isnan(b)) {
        return false;
    }
    double diff = fabs(a - b);
    if (diff <= eps) {
        return true;
    }
    double max_val = max(fabs(a), fabs(b));
    return (diff <= max_val * eps);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        cerr << "Usage: " << argv[0] << " <std_output> <user_output>" << endl;
        return 2;
    }

    string s_std = read_and_trim(argv[1]);
    string s_user = read_and_trim(argv[2]);

    // Check for the "impossible" case
    if (s_std == "impossible") {
        if (s_user == "impossible") {
            cout << "Accepted" << endl;
            return 0;
        } else {
            cout << "Wrong Answer" << endl;
            return 1;
        }
    }

    // If user claims "impossible" but it's not the case
    if (s_user == "impossible") {
        cout << "Wrong Answer" << endl;
        return 1;
    }

    double std_val, user_val;
    bool std_ok = parse_double(s_std, std_val);
    bool user_ok = parse_double(s_user, user_val);

    if (!std_ok) {
        cerr << "Internal Error: Standard output is invalid: '" << s_std << "'" << endl;
        return 2;
    }
    if (!user_ok) {
        cout << "Wrong Answer" << endl;
        return 1;
    }

    if (compare_floats(std_val, user_val, EPS)) {
        cout << "Accepted" << endl;
        return 0;
    } else {
        cout << "Wrong Answer" << endl;
        return 1;
    }
}
